// src/pages/StudentDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// Reusable Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

// Reusable Results Table Component
const ResultsTable = ({ position, candidates, winner }) => (
  <div style={{ marginBottom: "20px" }}>
    <h3>{position}</h3>
    <table style={{ width: "100%", borderCollapse: "collapse" }}>
      <thead>
        <tr style={{ background: "#f1f1f1" }}>
          <th style={{ padding: "8px" }}>Candidate</th>
          <th style={{ padding: "8px" }}>Party</th>
          <th style={{ padding: "8px", textAlign: "center" }}>Votes</th>
        </tr>
      </thead>
      <tbody>
        {candidates?.map((c) => (
          <tr key={c.id}>
            <td style={{ padding: "8px" }}>{c.name}</td>
            <td style={{ padding: "8px" }}>{c.party || "-"}</td>
            <td style={{ padding: "8px", textAlign: "center" }}>{c.votes}</td>
          </tr>
        ))}
      </tbody>
    </table>
    {winner && (
      <p style={{ fontWeight: "bold", color: "green" }}>
        Winner: {winner.name} ({winner.party || "-"})
      </p>
    )}
  </div>
);

export default function StudentDashboard() {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("Candidates");

  const [candidates, setCandidates] = useState([]);
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [myCandidacy, setMyCandidacy] = useState(null);

  const { logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchElections = async () => {
    try {
      const res = await api.get("/elections");
      const sorted = res.data
        .map((e) => ({
          ...e,
          startsAt: new Date(e.startsAt),
          endsAt: new Date(e.endsAt),
          isVotingOpen: new Date() >= new Date(e.startsAt) && new Date() <= new Date(e.endsAt),
          hasEnded: new Date() > new Date(e.endsAt),
        }))
        .sort((a, b) => b.startsAt - a.startsAt);

      setElections(sorted);

      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);

        if (firstElection.hasEnded) fetchResults(firstElection.id);
      }
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async (electionId) => {
    try {
      const res = await api.get("/results", { params: { electionId } });
      setResults(res.data.positionResults || {});
      setWinners(res.data.winners || {});
      setSelectedElection(electionId);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchMyCandidacy = async () => {
    try {
      const res = await api.get("/candidates/my-candidacy");
      setMyCandidacy(res.data || null);
    } catch (err) {
      if (err.response?.status === 404) setMyCandidacy(null);
      else handleApiError(err);
    }
  };

  useEffect(() => {
    fetchCandidates();
    fetchElections();
    fetchMyCandidacy();
  }, []);

  const renderContent = () => {
    const activeElection = elections.find((el) => el.id === selectedElection);

    switch (activeTab) {
      case "Candidates":
        if (!activeElection?.isVotingOpen) {
          return <Card title="Approved Candidates"><p>Voting is not open yet.</p></Card>;
        }

        return (
          <Card title="Approved Candidates">
            {candidates.length === 0 ? (
              <p>No candidates yet.</p>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px" }}>Name</th>
                    <th style={{ padding: "8px" }}>Position</th>
                    <th style={{ padding: "8px" }}>Party</th>
                  </tr>
                </thead>
                <tbody>
                  {candidates.map((c) => (
                    <tr key={c.id} style={{ borderTop: "1px solid #eee" }}>
                      <td style={{ padding: "8px" }}>{c.name}</td>
                      <td style={{ padding: "8px" }}>{c.position}</td>
                      <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Card>
        );

      case "Results":
        if (!activeElection?.hasEnded) {
          return <Card title="Election Results"><p>Results will be available after the election ends.</p></Card>;
        }

        return (
          <Card title="Election Results">
            {elections.length === 0 ? (
              <p>No elections available.</p>
            ) : (
              <>
                <select
                  value={selectedElection || ""}
                  onChange={(e) => fetchResults(parseInt(e.target.value))}
                  style={{ marginBottom: "15px", padding: "6px", borderRadius: "6px" }}
                >
                  {elections.map((el) => (
                    <option key={el.id} value={el.id}>{el.name}</option>
                  ))}
                </select>

                {Object.keys(results).length === 0 ? (
                  <p>No results available.</p>
                ) : (
                  Object.keys(results).map((pos) => (
                    <ResultsTable
                      key={pos}
                      position={pos}
                      candidates={results[pos]}
                      winner={winners[pos]}
                    />
                  ))
                )}
              </>
            )}
          </Card>
        );

      case "RegisterCandidacy":
        return (
          <Card title="My Candidacy Status">
            {!myCandidacy || myCandidacy.status === "none" ? (
              <p>You haven’t filed for candidacy yet.</p>
            ) : (
              <>
                <p><strong>Position:</strong> {myCandidacy.position}</p>
                <p>
                  <strong>Status:</strong>{" "}
                  {myCandidacy.approved === null && <span style={{ background: "#ffc107", color: "#000", padding: "4px 8px", borderRadius: "6px", fontWeight: "bold" }}>Pending</span>}
                  {myCandidacy.approved === true && <span style={{ background: "#28a745", color: "#fff", padding: "4px 8px", borderRadius: "6px", fontWeight: "bold" }}>Approved</span>}
                  {myCandidacy.approved === false && myCandidacy.rejectionComment && <span style={{ background: "#dc3545", color: "#fff", padding: "4px 8px", borderRadius: "6px", fontWeight: "bold" }}>Rejected</span>}
                </p>
                {myCandidacy.approved === false && myCandidacy.rejectionComment && (
                  <p style={{ color: "#dc3545", marginTop: "10px" }}><strong>Admin Comments:</strong> {myCandidacy.rejectionComment}</p>
                )}
              </>
            )}
            <button onClick={() => navigate("/register-candidacy")} style={{ marginTop: "15px", padding: "10px 20px", background: "#007bff", border: "none", borderRadius: "6px", color: "#fff", cursor: "pointer" }}>Go to Registration Form</button>
          </Card>
        );

      default:
        return null;
    }
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "Arial, sans-serif", background: "#f4f6f8" }}>
      {/* Sidebar */}
      <aside style={{ width: sidebarOpen ? "220px" : "60px", background: "#343a40", color: "#fff", transition: "width 0.3s", paddingTop: "20px" }}>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} style={{ background: "none", border: "none", color: "#fff", fontSize: "1.5rem", cursor: "pointer", marginLeft: sidebarOpen ? "180px" : "10px" }}>☰</button>
        <nav style={{ marginTop: "30px", display: "flex", flexDirection: "column", gap: "15px", paddingLeft: sidebarOpen ? "20px" : "5px" }}>
          <span style={{ cursor: "pointer" }} onClick={() => setActiveTab("Candidates")}>👤 Candidates</span>
          <span style={{ cursor: "pointer" }} onClick={() => setActiveTab("Results")}>📊 Results</span>
          <span style={{ cursor: "pointer" }} onClick={() => setActiveTab("RegisterCandidacy")}>📝 Register Candidacy</span>
          <button onClick={() => { logout(); navigate("/login"); }} style={{ marginTop: "auto", background: "#dc3545", color: "#fff", border: "none", padding: "10px", borderRadius: "6px", cursor: "pointer", fontWeight: "bold" }}>Logout</button>
        </nav>
      </aside>

      {/* Main */}
      <main style={{ flexGrow: 1, padding: "30px", maxWidth: "1000px", margin: "0 auto" }}>
        {renderContent()}
      </main>
    </div>
  );
}
